solution.code:
public class Main {
    public static void main(String[] args) {
        Box<String> name = new Box<>("Asha");
        System.out.println(name.get().toUpperCase());
    }
}

class Box<T> {
    private final T value;

    Box(T value) {
        this.value = value;
    }

    T get() {
        return value;
    }
}
